interface.definition:
a!localVariables(
  local!showRotational: or(
    a!isNullOrEmpty(ri!typeFilter),
    ri!typeFilter = "Rotational"
  ),
  local!showCore: or(
    a!isNullOrEmpty(ri!typeFilter),
    ri!typeFilter = "Core"
  ),
  local!filteredTotalConfirmed: if(
    a!isNullOrEmpty(ri!typeFilter),
    sum(
      index(ri!rotationalActual,"traditionalComplete",0),
      index(ri!rotationalActual,"earlyCareerComplete",0),
      index(ri!nonAskActual,"transitionalComplete",0),
      index(ri!nonAskActual,"otherCoreComplete",0),
      index(ri!nonAskActual,"otherRotationalComplete",0)
    ),
    if(
      ri!typeFilter = "Rotational",
      sum(
        index(ri!rotationalActual,"traditionalComplete",0),
        index(ri!rotationalActual,"earlyCareerComplete",0),
        index(ri!nonAskActual,"otherRotationalComplete",0)
      ),
      sum(
        index(ri!nonAskActual,"transitionalComplete",0),
        index(ri!nonAskActual,"otherCoreComplete",0)
      )
    )
  ),
  local!filteredTotalInProcess: if(
    a!isNullOrEmpty(ri!typeFilter),
    sum(
      index(ri!rotationalActual,"traditionalInProcess",0),
      index(ri!rotationalActual,"earlyCareerInProcess",0),
      index(ri!nonAskActual,"transitionalInProcess",0),
      index(ri!nonAskActual,"otherCoreInProcess",0),
      index(ri!nonAskActual,"otherRotationalInProcess",0)
    ),
    if(
      ri!typeFilter = "Rotational",
      sum(
        index(ri!rotationalActual,"traditionalInProcess",0),
        index(ri!rotationalActual,"earlyCareerInProcess",0),
        index(ri!nonAskActual,"otherRotationalInProcess",0)
      ),
      sum(
        index(ri!nonAskActual,"transitionalInProcess",0),
        index(ri!nonAskActual,"otherCoreInProcess",0)
      )
    )
  ),
  #"SYSTEM_SYSRULES_cardLayout"(
    contents: #"SYSTEM_SYSRULES_columnsLayout"(
      columns: {
        /* BUs */
        #"SYSTEM_SYSRULES_columnLayout"(
          contents: #"SYSTEM_SYSRULES_cardLayout"(
            contents: {
              #"SYSTEM_SYSRULES_forEach"(
                items: ri!bus,
                expression: #"SYSTEM_SYSRULES_richTextDisplayField"(
                  preventWrapping: true,
                  labelPosition: "COLLAPSED",
                  value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                    text: fv!item.bu,
                    color: if(
                      mod(fv!index,2)=0,
                      "ACCENT",
                      "STANDARD"
                    )
                  )
                )
              ),
              #"SYSTEM_SYSRULES_richTextDisplayField"(
                labelPosition: "COLLAPSED",
                value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                  text: if(
                    index(index(ri!bus,1,{}),"regionId",0) = 23,
                    "East Total",
                    "West Total"
                  ),
                  style: "STRONG"
                )
              )
            },
            showBorder: false
          ),
          width: "NARROW"
        ),
        /*Rotational Ask Columns*/
        #"SYSTEM_SYSRULES_columnLayout"(
          contents: #"SYSTEM_SYSRULES_cardLayout"(
            contents: #"SYSTEM_SYSRULES_columnsLayout"(
              columns: {
                /* Plan */
                #"SYSTEM_SYSRULES_columnLayout"(
                  contents: {
                    #"SYSTEM_SYSRULES_forEach"(
                      items: ri!bus,
                      expression: #"SYSTEM_SYSRULES_richTextDisplayField"(
                        labelPosition: "COLLAPSED",
                        value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                          text: #"_a-0000e7f4-9a94-8000-9c23-011c48011c48_6635835"(
                            index(
                              index(
                                ri!rotationalPlanned,
                                wherecontains(
                                  fv!item.buId,
                                  tointeger(index(ri!rotationalPlanned,"buId",{}))
                                )
                              ),
                              "plan",
                              {}
                            )  
                          ),
                          color: if(
                            mod(fv!index,2)=0,
                            "ACCENT",
                            "STANDARD"
                          )
                        ),
                        align: "CENTER"
                      )
                    ),
                    #"SYSTEM_SYSRULES_richTextDisplayField"(
                      labelPosition: "COLLAPSED",
                      value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                        text: #"_a-0000e7f4-9a94-8000-9c23-011c48011c48_6635835"(sum(index(ri!rotationalPlanned,"plan",{}))),
                        style: "STRONG"
                      ),
                      align: "CENTER"
                    )
                  },
                  width: "EXTRA_NARROW"
                ),
                /*Traditional Rotationals*/
                #"SYSTEM_SYSRULES_columnLayout"(
                  contents: #"SYSTEM_SYSRULES_columnsLayout"(
                    columns: {
                      #"SYSTEM_SYSRULES_columnLayout"(
                        contents: {
                          #"SYSTEM_SYSRULES_forEach"(
                            items: ri!bus,
                            expression: #"SYSTEM_SYSRULES_richTextDisplayField"(
                              labelPosition: "COLLAPSED",
                              value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                                text: #"_a-0000e7f4-9a94-8000-9c23-011c48011c48_6635835"(
                                  index(
                                    index(
                                      ri!rotationalActual,
                                      wherecontains(
                                        fv!item.buId,
                                        tointeger(index(ri!rotationalActual,"buId",{}))
                                      ),
                                      {}
                                    ),
                                    "traditionalComplete",
                                    0
                                  )
                                ),
                                color: if(
                                  mod(fv!index,2)=0,
                                  "ACCENT",
                                  "STANDARD"
                                )
                              ),
                              align: "CENTER"
                            )
                          ),
                          #"SYSTEM_SYSRULES_richTextDisplayField"(
                            labelPosition: "COLLAPSED",
                            value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                              text: #"_a-0000e7f4-9a94-8000-9c23-011c48011c48_6635835"(
                                sum(index(ri!rotationalActual,"traditionalComplete",0))
                              ),
                              style: "STRONG"
                            ),
                            align: "CENTER"
                          )
                        }
                      ),
                      #"SYSTEM_SYSRULES_columnLayout"(
                        contents: {
                          #"SYSTEM_SYSRULES_forEach"(
                            items: ri!bus,
                            expression: #"SYSTEM_SYSRULES_richTextDisplayField"(
                              labelPosition: "COLLAPSED",
                              value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                                text: #"_a-0000e7f4-9a94-8000-9c23-011c48011c48_6635835"(
                                  index(
                                    index(
                                      ri!rotationalActual,
                                      wherecontains(
                                        fv!item.buId,
                                        tointeger(index(ri!rotationalActual,"buId",{}))
                                      ),
                                      {}
                                    ),
                                    "traditionalInProcess"
                                  )
                                ),
                                color: if(
                                  mod(fv!index,2)=0,
                                  "ACCENT",
                                  "STANDARD"
                                )
                              ),
                              align: "CENTER"
                            )
                          ),
                          #"SYSTEM_SYSRULES_richTextDisplayField"(
                            labelPosition: "COLLAPSED",
                            value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                              text: #"_a-0000e7f4-9a94-8000-9c23-011c48011c48_6635835"(
                                sum(index(ri!rotationalActual,"traditionalInProcess",0))
                              ),
                              style: "STRONG"
                            ),
                            align: "CENTER"
                          )
                        }
                      )
                    },
                    spacing: "NONE"
                  )
                ),
                /*Early Career Rotationals*/
                #"SYSTEM_SYSRULES_columnLayout"(
                  contents: #"SYSTEM_SYSRULES_columnsLayout"(
                    columns: {
                      #"SYSTEM_SYSRULES_columnLayout"(
                        contents: {
                          #"SYSTEM_SYSRULES_forEach"(
                            items: ri!bus,
                            expression: #"SYSTEM_SYSRULES_richTextDisplayField"(
                              labelPosition: "COLLAPSED",
                              value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                                text: #"_a-0000e7f4-9a94-8000-9c23-011c48011c48_6635835"(
                                  index(
                                    index(
                                      ri!rotationalActual,
                                      wherecontains(
                                        fv!item.buId,
                                        tointeger(index(ri!rotationalActual,"buId",{}))
                                      ),
                                      {}
                                    ),
                                    "earlyCareerComplete",
                                    0
                                  )
                                ),
                                color: if(
                                  mod(fv!index,2)=0,
                                  "ACCENT",
                                  "STANDARD"
                                )
                              ),
                              align: "CENTER"
                            )
                          ),
                          #"SYSTEM_SYSRULES_richTextDisplayField"(
                            labelPosition: "COLLAPSED",
                            value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                              text: #"_a-0000e7f4-9a94-8000-9c23-011c48011c48_6635835"(
                                sum(index(ri!rotationalActual,"earlyCareerComplete",0))
                              ),
                              style: "STRONG"
                            ),
                            align: "CENTER"
                          )
                        }
                      ),
                      #"SYSTEM_SYSRULES_columnLayout"(
                        contents: {
                          #"SYSTEM_SYSRULES_forEach"(
                            items: ri!bus,
                            expression: #"SYSTEM_SYSRULES_richTextDisplayField"(
                              labelPosition: "COLLAPSED",
                              value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                                text: #"_a-0000e7f4-9a94-8000-9c23-011c48011c48_6635835"(
                                  index(
                                    index(
                                      ri!rotationalActual,
                                      wherecontains(
                                        fv!item.buId,
                                        tointeger(index(ri!rotationalActual,"buId",{}))
                                      ),
                                      {}
                                    ),
                                    "earlyCareerInProcess",
                                    0
                                  )
                                ),
                                color: if(
                                  mod(fv!index,2)=0,
                                  "ACCENT",
                                  "STANDARD"
                                )
                              ),
                              align: "CENTER"
                            )
                          ),
                          #"SYSTEM_SYSRULES_richTextDisplayField"(
                            labelPosition: "COLLAPSED",
                            value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                              text: #"_a-0000e7f4-9a94-8000-9c23-011c48011c48_6635835"(
                                sum(index(ri!rotationalActual,"earlyCareerInProcess",0))
                              ),
                              style: "STRONG"
                            ),
                            align: "CENTER"
                          )
                        }
                      )
                    },
                    spacing: "NONE"
                  )
                ),
                /*Variance*/
                #"SYSTEM_SYSRULES_columnLayout"(
                  contents: {
                    #"SYSTEM_SYSRULES_forEach"(
                      items: ri!bus,
                      expression: #"SYSTEM_SYSRULES_richTextDisplayField"(
                        labelPosition: "COLLAPSED",
                        value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                          text: #"_a-0000e7f4-9a94-8000-9c23-011c48011c48_6636024"(
                            sum(
                              index(
                                index(
                                  ri!rotationalActual,
                                  wherecontains(
                                    fv!item.buId,
                                    tointeger(index(ri!rotationalActual,"buId",{}))
                                  ),
                                  {}
                                ),
                                "traditionalComplete",
                                0
                              ),
                              index(
                                index(
                                  ri!rotationalActual,
                                  wherecontains(
                                    fv!item.buId,
                                    tointeger(index(ri!rotationalActual,"buId",{}))
                                  ),
                                  {}
                                ),
                                "traditionalInProcess",
                                0
                              ),
                              index(
                                index(
                                  ri!rotationalActual,
                                  wherecontains(
                                    fv!item.buId,
                                    tointeger(index(ri!rotationalActual,"buId",{}))
                                  ),
                                  {}
                                ),
                                "earlyCareerComplete",
                                0
                              ),
                              index(
                                index(
                                  ri!rotationalActual,
                                  wherecontains(
                                    fv!item.buId,
                                    tointeger(index(ri!rotationalActual,"buId",{}))
                                  ),
                                  {}
                                ),
                                "earlyCareerInProcess",
                                0
                              )
                            ) - index(
                              index(
                                ri!rotationalPlanned,
                                wherecontains(
                                  fv!item.buId,
                                  tointeger(index(ri!rotationalPlanned,"buId",{}))
                                )
                              ),
                              "plan",
                              0
                            )
                          ),
                          color: "NEGATIVE"
                        ),
                        align: "CENTER"
                      )
                    ),
                    #"SYSTEM_SYSRULES_richTextDisplayField"(
                      labelPosition: "COLLAPSED",
                      value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                        text: #"_a-0000e7f4-9a94-8000-9c23-011c48011c48_6636024"(
                          sum(
                            index(ri!rotationalActual,"traditionalComplete",0),
                            index(ri!rotationalActual,"traditionalInProcess",0),
                            index(ri!rotationalActual,"earlyCareerComplete",0),
                            index(ri!rotationalActual,"earlyCareerInProcess",0)
                          ) - sum(
                            index(ri!rotationalPlanned,"plan",{})
                          )
                        ),
                        color: "NEGATIVE",
                        style: "STRONG"
                      ),
                      align: "CENTER"
                    )
                  },
                  width: "EXTRA_NARROW"
                )
              },
              showDividers: true
            ),
            showBorder: false
          ),
          width: if(
            #"SYSTEM_SYSRULES_isPageWidth"({"DESKTOP_NARROW","DESKTOP"}),
            "MEDIUM",
            "WIDE"
          ),
          showWhen: local!showRotational
        ),
        /*Non-traditional Rotational Columns*/
        #"SYSTEM_SYSRULES_columnLayout"(
          contents: #"SYSTEM_SYSRULES_cardLayout"(
            contents: #"SYSTEM_SYSRULES_columnsLayout"(
            columns: {
              #"SYSTEM_SYSRULES_columnLayout"(
                contents: {
                  #"SYSTEM_SYSRULES_forEach"(
                    items: ri!bus,
                    expression: #"SYSTEM_SYSRULES_richTextDisplayField"(
                      labelPosition: "COLLAPSED",
                      value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                        text: #"_a-0000e7f4-9a94-8000-9c23-011c48011c48_6635835"(
                          index(
                            index(
                              ri!nonAskActual,
                              wherecontains(
                                fv!item.buId,
                                tointeger(index(ri!nonAskActual,"buId",{}))
                              ),
                              {}
                            ),
                            "otherRotationalComplete",
                            0
                          )
                        ),
                        color: if(
                          mod(fv!index,2)=0,
                          "ACCENT",
                          "STANDARD"
                        )
                      ),
                      align: "CENTER"
                    )
                  ),
                  #"SYSTEM_SYSRULES_richTextDisplayField"(
                    labelPosition: "COLLAPSED",
                    value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                      text: #"_a-0000e7f4-9a94-8000-9c23-011c48011c48_6635835"(
                        sum(index(ri!nonAskActual,"otherRotationalComplete",0))
                      ),
                      style: "STRONG"
                    ),
                    align: "CENTER"
                  )
                }
              ),
              #"SYSTEM_SYSRULES_columnLayout"(
                contents: {
                  #"SYSTEM_SYSRULES_forEach"(
                    items: ri!bus,
                    expression: #"SYSTEM_SYSRULES_richTextDisplayField"(
                      labelPosition: "COLLAPSED",
                      value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                        text: #"_a-0000e7f4-9a94-8000-9c23-011c48011c48_6635835"(
                          index(
                            index(
                              ri!nonAskActual,
                              wherecontains(
                                fv!item.buId,
                                tointeger(index(ri!nonAskActual,"buId",{}))
                              ),
                              {}
                            ),
                            "otherRotationalInProcess",
                            0
                          )
                        ),
                        color: if(
                          mod(fv!index,2)=0,
                          "ACCENT",
                          "STANDARD"
                        )
                      ),
                      align: "CENTER"
                    )
                  ),
                  #"SYSTEM_SYSRULES_richTextDisplayField"(
                    labelPosition: "COLLAPSED",
                    value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                      text: #"_a-0000e7f4-9a94-8000-9c23-011c48011c48_6635835"(
                        sum(index(ri!nonAskActual,"otherRotationalInProcess",0))
                      ),
                      style: "STRONG"
                    ),
                    align: "CENTER"
                  )
                }
              )
            },
            spacing: "NONE"
          ),
            showBorder: false
          ),
          width: "NARROW",
          showWhen: local!showRotational
        ),
        /*Transitional Core*/
        #"SYSTEM_SYSRULES_columnLayout"(
          contents: #"SYSTEM_SYSRULES_cardLayout"(
            contents: #"SYSTEM_SYSRULES_columnsLayout"(
              columns: {
                #"SYSTEM_SYSRULES_columnLayout"(
                  contents: {
                    #"SYSTEM_SYSRULES_forEach"(
                      items: ri!bus,
                      expression: #"SYSTEM_SYSRULES_richTextDisplayField"(
                        labelPosition: "COLLAPSED",
                        value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                          text: #"_a-0000e7f4-9a94-8000-9c23-011c48011c48_6635835"(
                            index(
                              index(
                                ri!nonAskActual,
                                wherecontains(
                                  fv!item.buId,
                                  tointeger(index(ri!nonAskActual,"buId",{}))
                                ),
                                {}
                              ),
                              "transitionalComplete",
                              0
                            )
                          ),
                          color: if(
                            mod(fv!index,2)=0,
                            "ACCENT",
                            "STANDARD"
                          )
                        ),
                        align: "CENTER"
                      )
                    ),
                    #"SYSTEM_SYSRULES_richTextDisplayField"(
                      labelPosition: "COLLAPSED",
                      value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                        text: #"_a-0000e7f4-9a94-8000-9c23-011c48011c48_6635835"(
                          sum(index(ri!nonAskActual,"transitionalComplete",0))
                        ),
                        style: "STRONG"
                      ),
                      align: "CENTER"
                    )
                  }
                ),
                #"SYSTEM_SYSRULES_columnLayout"(
                  contents: {
                    #"SYSTEM_SYSRULES_forEach"(
                      items: ri!bus,
                      expression: #"SYSTEM_SYSRULES_richTextDisplayField"(
                        labelPosition: "COLLAPSED",
                        value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                          text: #"_a-0000e7f4-9a94-8000-9c23-011c48011c48_6635835"(
                            index(
                              index(
                                ri!nonAskActual,
                                wherecontains(
                                  fv!item.buId,
                                  tointeger(index(ri!nonAskActual,"buId",{}))
                                ),
                                {}
                              ),
                              "transitionalInProcess",
                              0
                            )
                          ),
                          color: if(
                            mod(fv!index,2)=0,
                            "ACCENT",
                            "STANDARD"
                          )
                        ),
                        align: "CENTER"
                      )
                    ),
                    #"SYSTEM_SYSRULES_richTextDisplayField"(
                      labelPosition: "COLLAPSED",
                      value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                        text: #"_a-0000e7f4-9a94-8000-9c23-011c48011c48_6635835"(
                          sum(index(ri!nonAskActual,"transitionalInProcess",0))
                        ),
                        style: "STRONG"
                      ),
                      align: "CENTER"
                    )
                  }
                )
              },
              spacing: "NONE"
            ),
            showBorder: false
          ),
          width: "NARROW",
          showWhen: local!showCore
        ),
        /*Other Core*/
        #"SYSTEM_SYSRULES_columnLayout"(
          contents: #"SYSTEM_SYSRULES_cardLayout"(
            contents: #"SYSTEM_SYSRULES_columnsLayout"(
              columns: {
                #"SYSTEM_SYSRULES_columnLayout"(
                  contents: {
                    #"SYSTEM_SYSRULES_forEach"(
                      items: ri!bus,
                      expression: #"SYSTEM_SYSRULES_richTextDisplayField"(
                        labelPosition: "COLLAPSED",
                        value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                          text: #"_a-0000e7f4-9a94-8000-9c23-011c48011c48_6635835"(
                            index(
                              index(
                                ri!nonAskActual,
                                wherecontains(
                                  fv!item.buId,
                                  tointeger(index(ri!nonAskActual,"buId",{}))
                                ),
                                {}
                              ),
                              "otherCoreComplete",
                              0
                            )
                          ),
                          color: if(
                            mod(fv!index,2)=0,
                            "ACCENT",
                            "STANDARD"
                          )
                        ),
                        align: "CENTER"
                      )
                    ),
                    #"SYSTEM_SYSRULES_richTextDisplayField"(
                      labelPosition: "COLLAPSED",
                      value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                        text: #"_a-0000e7f4-9a94-8000-9c23-011c48011c48_6635835"(
                          sum(index(ri!nonAskActual,"otherCoreComplete",0))
                        ),
                        style: "STRONG"
                      ),
                      align: "CENTER"
                    )
                  }
                ),
                #"SYSTEM_SYSRULES_columnLayout"(
                  contents: {
                    #"SYSTEM_SYSRULES_forEach"(
                      items: ri!bus,
                      expression: #"SYSTEM_SYSRULES_richTextDisplayField"(
                        labelPosition: "COLLAPSED",
                        value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                          text: #"_a-0000e7f4-9a94-8000-9c23-011c48011c48_6635835"(
                            index(
                              index(
                                ri!nonAskActual,
                                wherecontains(
                                  fv!item.buId,
                                  tointeger(index(ri!nonAskActual,"buId",{}))
                                ),
                                {}
                              ),
                              "otherCoreInProcess",
                              0
                            )
                          ),
                          color: if(
                            mod(fv!index,2)=0,
                            "ACCENT",
                            "STANDARD"
                          )
                        ),
                        align: "CENTER"
                      )
                    ),
                    #"SYSTEM_SYSRULES_richTextDisplayField"(
                      labelPosition: "COLLAPSED",
                      value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                        text: #"_a-0000e7f4-9a94-8000-9c23-011c48011c48_6635835"(
                          sum(index(ri!nonAskActual,"otherCoreInProcess",0))
                        ),
                        style: "STRONG"
                      ),
                      align: "CENTER"
