                  }
                )
              },
              spacing: "NONE"
            ),
            showBorder: false
          ),
          width: "NARROW",
          showWhen: local!showCore
        ),
        /*Total*/
        #"SYSTEM_SYSRULES_columnLayout"(
          width: "NARROW",
          contents: #"SYSTEM_SYSRULES_cardLayout"(
            contents: #"SYSTEM_SYSRULES_columnsLayout"(
              columns: {
                #"SYSTEM_SYSRULES_columnLayout"(
                  contents: {
                    #"SYSTEM_SYSRULES_forEach"(
                      items: ri!bus,
                      expression: #"SYSTEM_SYSRULES_richTextDisplayField"(
                        labelPosition: "COLLAPSED",
                        value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                          text: if(
                            a!isNullOrEmpty(ri!typeFilter),
                            #"_a-0000e7f4-9a94-8000-9c23-011c48011c48_6635835"(
                              sum(
                                index(
                                  index(
                                    ri!rotationalActual,
                                    wherecontains(
                                      fv!item.buId,
                                      tointeger(index(ri!rotationalActual,"buId",{}))
                                    ),
                                    {}
                                  ),
                                  "traditionalComplete",
                                  0
                                ),
                                index(
                                  index(
                                    ri!rotationalActual,
                                    wherecontains(
                                      fv!item.buId,
                                      tointeger(index(ri!rotationalActual,"buId",{}))
                                    ),
                                    {}
                                  ),
                                  "earlyCareerComplete",
                                  0
                                ),
                                index(
                                  index(
                                    ri!nonAskActual,
                                    wherecontains(
                                      fv!item.buId,
                                      tointeger(index(ri!nonAskActual,"buId",{}))
                                    ),
                                    {}
                                  ),
                                  "transitionalComplete",
                                  0
                                ),
                                index(
                                  index(
                                    ri!nonAskActual,
                                    wherecontains(
                                      fv!item.buId,
                                      tointeger(index(ri!nonAskActual,"buId",{}))
                                    ),
                                    {}
                                  ),
                                  "otherCoreComplete",
                                  0
                                ),
                                index(
                                  index(
                                    ri!nonAskActual,
                                    wherecontains(
                                      fv!item.buId,
                                      tointeger(index(ri!nonAskActual,"buId",{}))
                                    ),
                                    {}
                                  ),
                                  "otherRotationalComplete",
                                  0
                                )
                              )
                            ),
